package grammar

func init() {
	planFlag := required("plan", "ID|URN", "plan id or URN")
	taskFlag := required("task", "ID|URN", "task id, or a task URN, which names its plan")
	optionalPlanFlag := optional("plan", "ID|URN", "plan id or URN; required unless --task is a task URN")
	repoFlag := optional("repo", "PATH", "code checkout when separate")
	commands = append(commands,
		Command{Name: "plan add-phase", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan add-phase --plan ID|URN --id ID --title TEXT [--json] <saga>", Summary: "add a named phase to the end of a Plan's order; a phase is not a dependency", Flags: []Flag{planFlag, required("id", "ID", "stable phase id"), required("title", "TEXT", "phase title"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan add-prototype", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan add-prototype --plan ID|URN --prototype URN [--json] <saga>", Summary: "attach a prototype that shows what a Plan will build", Flags: []Flag{planFlag, required("prototype", "URN", "prototype URN"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan create", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan create --id ID --title TEXT [--objective TEXT] [--json] <saga>", Summary: "create a Plan and its empty deck: one body of work, where its technical design is drafted", Flags: []Flag{required("id", "ID", "stable plan id"), required("title", "TEXT", "plan title"), optional("objective", "TEXT", "what the plan's deck explains"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan deliver", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan deliver --plan ID|URN [--repo PATH] [--json] <saga>", Summary: "mark a Plan delivered, which hides it by default as a merged review is hidden; refused unless every Task is done and every linked Review has merged", Flags: []Flag{planFlag, repoFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan link-review", Status: StatusImplemented, Mutates: true, Writes: []string{"plan"}, Usage: "change-saga plan link-review --plan ID|URN --review ID [--json] <saga>", Summary: "record a pull request review that implements a Plan; the review shows the link back", Flags: []Flag{planFlag, required("review", "ID", "review id"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "plan list", Status: StatusImplemented, Usage: "change-saga plan list [--feature ID] [--story URN] [--all] [--json] <saga>", Summary: "list the Plans with their Task progress and the stories and features their Tasks reach; the text hides delivered Plans unless --all", Flags: []Flag{optional("feature", "ID", "only Plans whose Tasks reach a story in this feature"), optional("story", "URN", "only Plans with a Task naming this story"), optional("all", "", "also print delivered Plans"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task add", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task add --plan ID|URN --id ID --title TEXT (--story URN | --unblocks TASK...) [--depends-on TASK...] [--phase ID] [--essay-source FILE|-] [--code PATH:START-END[=NOTE]...] [--sizing within-2-days|over-2-days] [--sizing-reason TEXT] [--repo PATH] [--json] <saga>", Summary: "add a Task to a Plan; it must name a user story or unblock a Task that leads to one, and is refused otherwise", Flags: []Flag{planFlag, required("id", "ID", "stable task id"), required("title", "TEXT", "task title"), optional("story", "URN", "the user story this task is part of"), repeatable("unblocks", "TASK", "a task that depends on this one", false), repeatable("depends-on", "TASK", "a task this one depends on", false), optional("phase", "ID", "phase id"), optional("essay-source", "FILE|-", "Markdown essay"), repeatable("code", "PATH:START-END[=NOTE]", "code to pin at HEAD", false), optional("sizing", "VALUE", "within-2-days or over-2-days: whether this would have taken two days or less before AI"), optional("sizing-reason", "TEXT", "why"), repoFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task depend", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task depend [--plan ID|URN] --task ID|URN --on TASK [--remove] [--json] <saga>", Summary: "add or remove a dependency between two Tasks of a Plan; refused when it would make a cycle or strand a Task", Flags: []Flag{optionalPlanFlag, taskFlag, required("on", "TASK", "the task it depends on"), optional("remove", "", "remove the dependency instead"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task done", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task done [--plan ID|URN] --task ID|URN [--summary TEXT] [--json] <saga>", Summary: "mark a Task done, as an agent does when it finishes; the slides that name it show this without being republished; it never proves the work is correct", Flags: []Flag{optionalPlanFlag, taskFlag, optional("summary", "TEXT", "what was done"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task list", Status: StatusImplemented, Usage: "change-saga task list --plan ID|URN [--ready] [--json] <saga>", Summary: "list a Plan's Tasks; --ready lists what can start now, in parallel, because everything it depends on is done", Flags: []Flag{planFlag, optional("ready", "", "only Tasks that can start now"), jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task remove", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task remove [--plan ID|URN] --task ID|URN [--json] <saga>", Summary: "delete a Task and every dependency on it; refused when that would strand a Task or a slide still names it", Flags: []Flag{optionalPlanFlag, taskFlag, jsonFlag}, Positionals: sagaOnly},
		Command{Name: "task set", Status: StatusImplemented, Mutates: true, Writes: []string{"task"}, Usage: "change-saga task set [--plan ID|URN] --task ID|URN [--title TEXT] [--phase ID] [--story URN] [--state STATE] [--essay-source FILE|-] [--code PATH:START-END[=NOTE]...] [--sizing within-2-days|over-2-days] [--sizing-reason TEXT] [--repo PATH] [--json] <saga>", Summary: "change a Task's fields; refused when the result would strand a Task", Flags: []Flag{optionalPlanFlag, taskFlag, optional("title", "TEXT", "task title"), optional("phase", "ID", "phase id; empty clears it"), optional("story", "URN", "user story; empty clears it"), optional("state", "STATE", "planned, in_progress, or done"), optional("essay-source", "FILE|-", "Markdown essay; an empty file removes it"), repeatable("code", "PATH:START-END[=NOTE]", "code to pin at HEAD; replaces the task's references", false), optional("sizing", "VALUE", "within-2-days or over-2-days"), optional("sizing-reason", "TEXT", "why"), repoFlag, jsonFlag}, Positionals: sagaOnly},
	)
	resources = append(resources,
		Resource{Kind: "plan", URN: "urn:change-saga:<saga>:plan:<plan>", Storage: "___plans/<plan>.plan/plan.json and deck/ (a flat deck bundle, role plan)", Schema: schemaBase + "v5/plan.schema.json", Versions: []int{5}, History: "editable current state; Git keeps the history; a delivered Plan no longer changes", Writers: []string{"plan create", "plan add-phase", "plan add-prototype", "plan link-review", "plan deliver"}, Notes: "one body of work, in its own section beside Documentation and Reviews; it belongs to no feature, and its stories and features are worked out from its Tasks; its slide and Item URNs are <plan>:slide:<slide>[:item:<item>]; it never counts toward coverage"},
		Resource{Kind: "task", URN: "urn:change-saga:<saga>:plan:<plan>:task:<task>", Storage: "___plans/<plan>.plan/tasks/<task>.task/task.json and optional essay.md", Schema: schemaBase + "v5/task.schema.json", Versions: []int{5}, Lifecycle: []string{"planned", "in_progress", "done"}, History: "editable current state; Git keeps the history", Writers: []string{"task add", "task depend", "task set", "task done", "task remove"}, Notes: "must name a user story or unblock a Task that leads to one; what it unblocks is derived from depends_on, and dependencies stay inside one Plan"},
	)
}
